194	\begin{lemma}[Product form and Pauli relations of the pulled-apart observables]\label{lem:tildew-product-form}
195		\lean{MIPStarRE.QPBT.tildeObs_eq_heteroKron}
196		\lean{MIPStarRE.QPBT.tildeObs_isHermitian}
197		\lean{MIPStarRE.QPBT.tildeObs_mul_self}
