207		\begin{equation}\label{eq:tildew-twisted-commutation}
208			\tilde{X}^j(\tilde{u})\, \tilde{Z}^{j'}(\tilde{v})
209			= (-1)^{\tr((e_j \tilde{u}) \cdot (e_{j'} \tilde{v}))}\, \tilde{Z}^{j'}(\tilde{v})\, \tilde{X}^j(\tilde{u})\;,
210		\end{equation}
211		where $\tr((e_j \tilde{u}) \cdot (e_{j'} \tilde{v})) = \tr(e_j e_{j'} (\tilde{u} \cdot \tilde{v}))$.
