383			\qquad \text{and} \qquad
384			V_{\mathrm{B}} \, \tilde{W}^j(\tilde{u}) \, V_{\mathrm{B}}^\dagger = \Id_{\mathrm{B}\mathrm{B}'} \ot \bigl( \tau^W(e_j \tilde{u}) \bigr)_{\mathrm{B}''}\;,
